"""Bundle the existing Python app into index.html for a static Hugging Face Space."""

from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parent

# Gradio-Lite uses Python 3.12 in a browser worker. Its older package installer
# needs compatible versions of these packages before it installs Gradio itself.
# These are the original wheels published on PyPI.
HEAD = """<!doctype html>
<!-- Generated by python build_space.py from the project's Python files and style.css. -->
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Shuttle Stop Crowd Ranking</title>
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@gradio/lite@5.45.0/dist/lite.css">
  <script>
    const wheels = [
      "https://files.pythonhosted.org/packages/fe/85/a18508becfa01f1e4351b5e18651b06d210dbd96debccd48a452acccb901/huggingface_hub-0.35.0-py3-none-any.whl",
      "https://files.pythonhosted.org/packages/46/eb/e7f063ad1fec6b3178a3cd82d1a3c4de82cccf283fc42746168188e1cdd5/anyio-4.8.0-py3-none-any.whl",
      "https://files.pythonhosted.org/packages/8b/0c/9d30a4ebeb6db2b25a841afbb80f6ef9a854fc3b41be131d249a977b4959/starlette-0.46.2-py3-none-any.whl",
      "https://files.pythonhosted.org/packages/50/b3/b51f09c2ba432a576fe63758bddc81f78f0c6309d9e5c10d194313bf021e/fastapi-0.115.12-py3-none-any.whl"
    ];

    // This function runs inside Gradio's worker, before Gradio imports Python packages.
    function pinPackages(urls) {
      const loadPython = self.loadPyodide;
      self.loadPyodide = async function (options) {
        const python = await loadPython(options);
        await python.loadPackage("micropip");
        const pip = python.pyimport("micropip");
        try {
          for (const url of urls) await pip.install(url);
        } finally {
          pip.destroy();
        }
        return python;
      };
    }

    // Wrap the one worker this page starts, then restore the normal constructor.
    const BrowserWorker = window.Worker;
    function startGradioWorker(url, options) {
      window.Worker = BrowserWorker;
      const startup =
        "importScripts(" + JSON.stringify(String(url)) + ");" +
        "(" + pinPackages.toString() + ")(" + JSON.stringify(wheels) + ");";
      const workerUrl = URL.createObjectURL(new Blob([startup], {type: "text/javascript"}));
      return new BrowserWorker(workerUrl, options);
    }
    window.Worker = startGradioWorker;
  </script>
  <script type="module" crossorigin src="https://cdn.jsdelivr.net/npm/@gradio/lite@5.45.0/dist/lite.js"></script>
  <style>
    body { margin: 0; font-family: system-ui, sans-serif; }
    gradio-lite { display: block; min-height: 100vh; }
    gradio-file { display: none; }
    /* Keep the project's colours and heading sizes above the Lite theme defaults. */
    #shuttle-space {
"""

BODY = """
    }
    #shuttle-space, #shuttle-space .gradio-container { --font-mono: ui-monospace, Menlo, Consolas, monospace; }
    #shuttle-space #controls textarea { font-family: var(--font-mono); }
  </style>
</head>
<body id="shuttle-space">
  <noscript>Enable JavaScript to load Python and run the shuttle simulation.</noscript>
  <gradio-lite theme="light">
"""

END = """    <gradio-file name="browser.py" entrypoint>
from app import build_app

build_app().launch()
    </gradio-file>
  </gradio-lite>
</body>
</html>
"""


def build():
    # Embedding the same source keeps the Space upload to one file. Escape '<'
    # and '&' so Python comparisons and HTML strings survive the HTML parser.
    parts = [HEAD, (ROOT / "style.css").read_text(encoding="utf-8"), BODY]
    for name in ("app.py", "ranking.py", "display.py"):
        source = (ROOT / name).read_text(encoding="utf-8")
        parts.append(f'    <gradio-file name="{name}">\n{escape(source, quote=False)}</gradio-file>\n')
    parts.append(END)
    (ROOT / "index.html").write_text("".join(parts), encoding="utf-8")


if __name__ == "__main__":
    build()
